import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

async function main() {
  const usersByCountry = await prisma.user.groupBy({
    by: ['country'],
    _sum: { profileViews: true },
    _count: { _all: true },
    orderBy: { country: 'asc' },
  });

  console.log(usersByCountry);
}

main().finally(() => prisma.$disconnect());

const users = await prisma.user.findMany({
  where: {
    email: { endsWith: "prisma.io" },
    OR: [
      { name: { contains: "Alice" } },
      { name: { contains: "Bob" } }
    ]
  }
});

const user = await prisma.user.create({
  data: {
    email: "alice@prisma.io",
    posts: {
      create: [
        { title: "First post" },
        { title: "Second post" }
      ]
    }
  }
});

const firstPage = await prisma.post.findMany({
  take: 10,
  orderBy: { id: "asc" },
});

const lastPost = firstPage[firstPage.length - 1];
const nextPage = lastPost
  ? await prisma.post.findMany({
      take: 10,
      skip: 1,
      cursor: { id: lastPost.id },
      orderBy: { id: "asc" },
    })
  : [];

const users = await prisma.user.findMany({
  select: {
    email: true,
    name: true,
    posts: {
      select: {
        title: true,
        published: true,
      },
    },
  },
});

