  id      String  @id @default(auto()) @map("_id") @db.ObjectId
  role    Role    @default(USER)
  address Address
}

model Post {
  id      Int     @id @default(autoincrement())
  title   String
  content String?

  @@index([title, content])
}

model User {
  id    Int     @id @default(autoincrement())
  email String  @unique
  name  String?
}

